/**
 * Image asset registry.
 *
 * Every entry points at a WebP derivative generated by `scripts/optimize-images.sh`
 * (`npm run images`). The original JPEG/TIFF masters stay in `src/assets/images/**`
 * and are deliberately never imported, so they are not part of the build output.
 *
 * Each image exposes:
 *   src    – primary URL (largest generated size, used as the fallback source)
 *   srcSet – width-descriptor candidates for the browser
 *   lqip   – ~500 byte blurred placeholder (progressive loading)
 *   full   – large version for the lightbox
 *
 * Variants are discovered with `import.meta.glob`, which keeps the Vite asset
 * pipeline (content hashing + long-term caching) while keeping this file readable.
 */

export interface Img {
  src: string;
  srcSet?: string;
  lqip?: string;
  /** Larger rendering used by the lightbox (falls back to `src`). */
  full?: string;
}

export interface GalleryItem {
  /** Grid sized rendering (~900px). */
  thumb: Img;
  /** Full size rendering used by the lightbox. */
  src: string;
  title: string;
  cat: string;
}

const files = import.meta.glob('./assets/opt/**/*.webp', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

function url(path: string): string {
  const found = files[`./assets/opt/${path}.webp`];
  if (!found && import.meta.env.DEV) {
    console.warn(`[assets] missing optimized image: src/assets/opt/${path}.webp — run "npm run images"`);
  }
  return found ?? '';
}

/** Builds one responsive image descriptor from `<dir>/<name>-<width>[@2x].webp` derivatives. */
function picture(
  dir: string,
  name: string,
  widths: number[],
  options: { lqip?: boolean; full?: number } = {}
): Img {
  const base = `${dir}/${name}`;
  const candidates = widths.map((w) => ({ w, url: url(`${base}-${w}`) }));
  const largest = candidates[candidates.length - 1];
  return {
    src: largest.url,
    srcSet: candidates.length > 1 ? candidates.map((c) => `${c.url} ${c.w}w`).join(', ') : undefined,
    lqip: options.lqip ? url(`${base}-lqip`) : undefined,
    full: options.full ? url(`${base}-${options.full}`) : undefined,
  };
}

